import logging
from dataclasses import dataclass, field
from typing import Mapping
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

logger = logging.getLogger(__name__)

SECRET_MASK = "***"
DEFAULT_BATCH_SIZE = 500
_ENV_PREFIX = "EXPORT_"
_SECRET_QUERY_KEYS = frozenset({"password", "passwd", "pwd", "secret", "token", "sslpassword"})
_BOOLEANS = {"true": True, "false": False}


@dataclass(frozen=True)
class JobConfig:
    db_url: str = field(repr=False)
    db_password: str = field(repr=False)
    batch_size: int
    dry_run: bool

    @property
    def masked(self) -> Mapping[str, object]:
        return {
            "db_url": mask_url(self.db_url),
            "db_password": SECRET_MASK,
            "batch_size": self.batch_size,
            "dry_run": self.dry_run,
        }


def mask_url(url: str) -> str:
    parts = urlsplit(url)
    netloc = parts.netloc
    if parts.password is not None:
        netloc = f"{parts.username}:{SECRET_MASK}@{parts.netloc.rpartition('@')[2]}"
    query = urlencode(
        [(key, SECRET_MASK if key.lower() in _SECRET_QUERY_KEYS else value) for key, value in parse_qsl(parts.query, keep_blank_values=True)],
        safe="*",
    )
    return urlunsplit((parts.scheme, netloc, parts.path, query, parts.fragment))


def _required(env: Mapping[str, str], name: str) -> str:
    if not env.get(name):
        raise ValueError(f"{name} is required and must be non-empty")
    return env[name]


def _batch_size(env: Mapping[str, str]) -> int:
    raw = env.get("EXPORT_BATCH_SIZE", str(DEFAULT_BATCH_SIZE))
    if not raw.isdecimal() or int(raw) < 1:
        raise ValueError(f"EXPORT_BATCH_SIZE must be a positive integer, got {raw!r}")
    return int(raw)


def _dry_run(env: Mapping[str, str]) -> bool:
    raw = env.get("EXPORT_DRY_RUN", "false")
    if raw.strip().lower() not in _BOOLEANS:
        raise ValueError(f"EXPORT_DRY_RUN must be 'true' or 'false', got {raw!r}")
    return _BOOLEANS[raw.strip().lower()]


def _masked_raw(env: Mapping[str, str]) -> Mapping[str, str]:
    raw = {name: value for name, value in env.items() if name.startswith(_ENV_PREFIX)}
    return {
        name: SECRET_MASK if name == "EXPORT_DB_PASSWORD" else mask_url(value) if name == "EXPORT_DB_URL" else value
        for name, value in raw.items()
    }


def load_job_config(env: Mapping[str, str]) -> JobConfig:
    """Single resolution point: all defaults, validation and masking-aware logging happen here."""
    logger.info("job config raw", extra={"config": _masked_raw(env)})
    config = JobConfig(
        db_url=_required(env, "EXPORT_DB_URL"),
        db_password=_required(env, "EXPORT_DB_PASSWORD"),
        batch_size=_batch_size(env),
        dry_run=_dry_run(env),
    )
    logger.info("job config resolved", extra={"config": config.masked})
    return config
